CREATE TABLE "notification" ("id" BIGSERIAL PRIMARY KEY, "recipient_user_id" BIGINT NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "event_key" VARCHAR(100) NOT NULL, "priority" VARCHAR(20) NOT NULL DEFAULT 'NORMAL', "title" VARCHAR(180) NOT NULL, "body" VARCHAR(500) NOT NULL, "deep_link" VARCHAR(500), "source_type" VARCHAR(80) NOT NULL, "source_id" VARCHAR(100), "dedupe_key" VARCHAR(255) NOT NULL UNIQUE, "read_at" TIMESTAMP(6), "expires_at" TIMESTAMP(6), "created_at" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "notification_recipient_user_id_read_at_created_at_idx" ON "notification"("recipient_user_id", "read_at", "created_at");
CREATE TABLE "notification_delivery" ("id" BIGSERIAL PRIMARY KEY, "notification_id" BIGINT NOT NULL REFERENCES "notification"("id") ON DELETE CASCADE, "channel" VARCHAR(30) NOT NULL, "status" VARCHAR(30) NOT NULL DEFAULT 'QUEUED', "attempt_count" INTEGER NOT NULL DEFAULT 0, "failure_reason" TEXT, "provider_message_id" VARCHAR(255), "sent_at" TIMESTAMP(6), "created_at" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "notification_delivery_status_created_at_idx" ON "notification_delivery"("status", "created_at");
CREATE TABLE "notification_preference" ("user_id" BIGINT PRIMARY KEY REFERENCES "users"("id") ON DELETE CASCADE, "push_enabled" BOOLEAN NOT NULL DEFAULT true, "quiet_hours_start" VARCHAR(5), "quiet_hours_end" VARCHAR(5), "updated_at" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "push_subscription" ("id" BIGSERIAL PRIMARY KEY, "user_id" BIGINT NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "endpoint" TEXT NOT NULL UNIQUE, "p256dh" TEXT NOT NULL, "auth" TEXT NOT NULL, "device_label" VARCHAR(100), "revoked_at" TIMESTAMP(6), "created_at" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "push_subscription_user_id_revoked_at_idx" ON "push_subscription"("user_id", "revoked_at");
